const raid = [
{ id:'nekzali',order:1,name:"Нек'зали, Заклинательница душ",en:"Nek'zali the Soulcoiler",summary:'Контроль Колодца душ, волн Амани и трупов на Heroic. Референс-бой 9:36 показывает длинную первую фазу, переход на 50% и финальную гонку урона после Раскручивания.',tags:['Адды','Колодец душ','Кремация','Рейдовый урон'],bl:'Сразу после перехода, когда Нек’зали возвращается и начинается Раскручивание.',rl:'Не кормим Колодец ни аддами, ни смертями. Разрыв сущности сбрасываем на внешнем краю. Босса двигаем к стороне с активными гробницами, чтобы Амани попадали под клив. Обстрел танк уводит по длинной линии. На Heroic трупы Амани сохраняются: в переходе используем Кремацию от Скользящего пламени, чтобы их убрать. После Раскручивания — героизм и дожим, но Амани всё ещё приоритетны, если близко к Колодцу.',heal:'Следить за Ритуальным ожогом: лишний Обряд Колодца резко повышает последующий урон. Крупные рейдовые КД распределить по Воспламенениям (в референсе ~0:00 / 1:22 / 2:44) и началу Раскручивания ~6:33. Разрыв сущности не снимать в общей группе. На Голодный костёр заранее поднять рейд и контролировать игроков, назначенных на Кремацию.',phases:[
['Фаза 1','Не кормим Колодец душ',[['Колодец душ','Soulcoil Well','Любой Амани, дошедший до центра, или смерть игрока внутри Колодца запускает Обряд Колодца душ и даёт боссу энергию.','all','danger','На Heroic Обряд дополнительно накладывает Ритуальный ожог: следующий Обряд становится опаснее.'],['Разрыв сущности','Essence Rend','Несколько игроков получают длительный эффект. Унести его на внешний край; при снятии/окончании там появится Латентный культист.','healer,dps','warning','Не создавать культистов в общей группе или на маршруте к Колодцу.'],['Восставшие амани','Restless Amani','Смотреть на светящиеся гробницы и вести босса к стороне с несколькими активными точками. Дальние ДД ломают защиту и контролят далёких аддов.','dps,tank','danger','После смерти Амани оставляют Сосуды пробуждения, которые могут снова ожить в переходе.'],['Обстрел одержимости','Possession Barrage','Танк направляет спектральные эхо вдоль максимально длинной свободной линии; рейд не стоит между боссом и краем.','tank,all','danger','Каждое эхо дополнительно накладывает Ослабленную душу/эффект Hollowed, поэтому лишние попадания особенно плохи.'],['Воспламенение Колодца','Soulcoil Ignition','Четырёхсекундная серия сильного рейдового урона и ударов по площадке. Хил-КД назначаются заранее.','healer,all','danger']]],
['Переход — 50%','Ритуал пробуждения',[['Эхо Джавэ','Echo of Jawae','Нек’зали неуязвима, пока активны связи пробуждения. Убиваем Эхо по очереди и рвём связи.','all','danger'],['Голодный костёр','Hungering Pyre','Большой урон делится между игроками внутри 10 ярдов. Основная группа собирается на Эхо.','all','danger','Игроки снаружи получают Скользящее пламя; его Кремация может уничтожать Сосуды пробуждения и Амани. Взрыв назначаем вдали от основной группы.']]],
['Финальная фаза','Раскручивание — гонка урона',[['Раскручивание','Uncoiling','Постоянный урон по всему рейду до конца боя. После возвращения босса используем героизм и оставшиеся КД.','all,healer','danger'],['Призыв','Invoke','Финальный цикл продолжает запускать Обряд Колодца и работу с аддами. Не прекращаем контролировать Амани ради чистого урона в босса.','all,dps','warning'],['Необузданная ярость','Uncoiled Rage','При полной энергии босс получает огромный прирост скорости и урона и перестаёт нормально танковаться — это фактический дедлайн.','all','danger']]]
],timeline:[['0:18','Разрыв сущности','move'],['0:56','Первая волна Амани','adds'],['1:22','Воспламенение №2','raid'],['4:06','Переход на 50%','adds'],['4:59','Голодный костёр','raid'],['6:33','Раскручивание + героизм','burst'],['6:50+','Призыв / Амани / Обстрел','adds']],spells:[['Колодец душ','Soulcoil Well'],['Обряд Колодца душ','Soulcoil Rite'],['Ритуальный ожог','Ritual Burn'],['Разрыв сущности','Essence Rend'],['Восставший амани','Restless Amani'],['Обстрел одержимости','Possession Barrage'],['Воспламенение Колодца','Soulcoil Ignition'],['Голодный костёр','Hungering Pyre'],['Кремация','Cremation'],['Раскручивание','Uncoiling'],['Призыв','Invoke']]},
{ id:'sentinels',order:2,name:'Погребённые часовые',en:'Entombed Sentinels',summary:'Heroic-референс 8:43.642: две стабильные команды, боссы строго разнесены, слизень всегда главный приоритет, а Ядовитый стазис повторяется пять раз и требует ровного здоровья обеих сторон.',tags:['2 группы','Слизень','Стазис','Дебаффы'],bl:'Обычно после 4-го стазиса или прямо на пулле по урону вашей группы. В референс-киле дожим идёт после последнего, 5-го стазиса.',rl:'Весь бой завязан на геометрию Heroic-пула: левая и правая команды почти не меняются. Боссов держим далеко друг от друга и не тянем к центру. Каждое Сгущение яда — мгновенный свитч в слизня. Токсичные капли и Осквернение раскладываем по своим сторонам, не перекрывая центральный проход. Цели с Инъекцией кровавого яда и Нестабильной миазмой сходятся только с назначенными игроками. На Ядовитом стазисе обе стороны собираются ближе к середине, но здоровье боссов всё время выравнивается.',heal:'Основные пики Heroic-референса: набор дебаффов после Сгущения яда и каждый Ядовитый стазис. Большие рейдовые КД лучше распределить под стазисы ~0:46, ~2:34, ~4:19, ~6:04 и ~7:45. Не диспелить/не схлопывать несколько тяжёлых дебаффов одновременно на одной стороне. Следите за перекосом урона по боссам: перед стазисом лишний перекачанный босс часто ломает попытку.',phases:[['Основная фаза','Heroic-ритм построен по реальному киллу',[['Разделение рейда','Split Teams','Левая и правая группы почти постоянные: по танку, хилу и набору ДД на каждую сторону.','all','warning'],['Власть Ула’тек',"Ula'tek's Dominance",'Боссы не должны подходить друг к другу. Если свести их слишком близко, они получают огромную защиту и бой ломается.','tank,all','danger'],['Сгущение яда','Venom Coagulation','Первый слизень в референсе выходит уже около 0:10. Каждый слизень — абсолютный приоритет ДД, но танки не двигают боссов к центру без необходимости.','dps,tank','danger'],['Токсичные капли и Осквернение','Toxic Droplets / Contaminate','После слизня быстро раскладываем лужи и эффекты по своим сторонам, освобождая центральный проход для следующей механики.','all','warning'],['Инъекция кровавого яда','Bloodvenom Injection','Назначенные цели не бегут хаотично через центр. Любые схлопывания/диспелы только по заранее понятной схеме.','all,healer','danger'],['Нестабильная миазма','Unstable Miasma','Игроки сходятся только в назначенные мини-группы, затем немедленно расходятся назад по сторонам.','all','danger'],['Проклятая кровь','Blighted Blood','Периодические тяжёлые пульсации урона перед стазисами. Заранее поднимаем рейд и готовим сейвы.','healer,all','warning']]],['Ядовитый стазис','Пять интермиссий в референсе',[['Ядовитый стазис','Vitriolic Stasis','Обе стороны собираются ближе к центру, но не ломают дистанцию между боссами раньше времени. Ключ — ровное здоровье и быстрый возврат к исходной геометрии после стазиса.','all','danger'],['Выравнивание здоровья','Even Boss Health','У Погребённых часовых нет общего здоровья, поэтому перед каждым стазисом и особенно перед финальным дожимом баланс урона критически важен.','dps,all','warning']]]],timeline:[['0:10','Сгущение яда #1','adds'],['0:46','Ядовитый стазис #1','raid'],['1:13','Сгущение яда #2','adds'],['2:34','Ядовитый стазис #2','raid'],['4:19','Ядовитый стазис #3','raid'],['6:04','Ядовитый стазис #4','raid'],['7:45','Ядовитый стазис #5','raid'],['8:43','Убийство','burst']],spells:[['Власть Ула’тек',"Ula'tek's Dominance"],['Сгущение яда','Venom Coagulation'],['Токсичные капли','Toxic Droplets'],['Осквернение','Contaminate'],['Инъекция кровавого яда','Bloodvenom Injection'],['Нестабильная миазма','Unstable Miasma'],['Проклятая кровь','Blighted Blood'],['Ядовитый стазис','Vitriolic Stasis']]},
{ id:'explorers',order:4,name:'Потерянные исследователи',en:'The Lost Explorers',summary:'Heroic-совет из трёх целей. Держим здоровье ровно, собираемся на Могучий удар и заранее назначаем три окна Отвратительной рыбы под Последнее вознесение.',tags:['Совет','Рыба','Soak','Выравнивание HP'],bl:'Обычно на старте, чтобы быстро стабилизировать HP всех трёх целей и не затягивать третий цикл. Если урон уверенный, можно придержать на финальный дожим после третьего Вознесения.',rl:'Три цели держим рядом и не перекошенно по здоровью. На каждом Могучем ударе весь рейд быстро собирается в одной точке и сразу возвращается на свои места. Последнее вознесение ломаем по заранее назначенному порядку рыбы A → B → C; следующий носитель готовится заранее и не бегает хаотично через арену. Огненные и ледяные эффекты раскладываем предсказуемо, чтобы к следующему сбору оставался чистый карман.',heal:'Главные пики Heroic — серия Могучего удара и поздние наложения огня с льдом. Малые КД можно дать на ранние soaks, крупные — на 2-й и 3-й циклы, особенно если они накладываются на Вознесение. Игроков с рыбой не терять из фокуса: они часто выходят из общей позиции.',phases:[['Основной цикл','Heroic-паттерн референса',[['Равное здоровье','Even Health','Не перекашивать HP трёх исследователей: держим аккуратный клив и переключаемся по необходимости.','dps','warning'],['Могучий удар','Mighty Thud','Групповой soak. Весь рейд быстро собирается в назначенной точке и не растягивается по комнате.','all','danger'],['Последнее вознесение','Final Ascension','Останавливается назначенной Отвратительной рыбой. Порядок носителей фиксируется до пула и повторяется без импровизации.','all','danger'],['Огненно-ледяные эффекты','Frostfire','Огонь и лёд раскладываем предсказуемо, чтобы не отрезать путь к месту следующего сбора.','all','warning']]],['Финальный цикл','Третий набор рыбы и дожим',[['Третье Вознесение','Final Ascension #3','Последняя рыба — ключ к чистому киллу. Не ломаем её спешкой и не уводим босса в мусорные лужи.','all','danger'],['Финальный дожим','Burn','После третьего Вознесения добиваем цели, сохраняя ровное здоровье и не теряя дисциплину на последнем Могучем ударе.','all','warning']]]],timeline:[['0:00','Пулл — клив и выравнивание','burst'],['0:36','Последнее вознесение #1 — рыба A','move'],['0:50','Могучий удар #1','raid'],['1:57','Последнее вознесение #2 — рыба B','move'],['2:35','Могучий удар #2','raid'],['4:32','Последнее вознесение #3 — рыба C','move'],['4:54','Огонь / лёд — позднее наложение','move'],['5:50','Финальный дожим','burst']],spells:[['Последнее вознесение','Final Ascension'],['Отвратительная рыба','Disgusting Fish'],['Найти рыбу','Find Fish'],['Могучий удар','Mighty Thud'],['Огненно-ледяный залп','Frostfire Volley']]},
{ id:'vashnik',order:3,name:'Вашник Злокачественный',en:'Vashnik the Malignant',summary:'Однофазный бой вокруг трёх источников. Танк позицией босса выбирает пару усилений; рейд разводит Чумную пену, перехватывает Каталитическую желчь и быстро убивает Живые яды.',tags:['Маршрут босса','Перехваты','Адды','Инфекции'],bl:'По решению рейда: на пулле для максимального урона либо на позднее Поглощение, если прогресс упирается в растущие Токсичные испарения.',rl:'Референс тестового убийства 8:08: Тень+Пламя → Кровь+Пламя → Кровь+Тень → повтор. Чумную пену выносим в назначенные края. После Поглощения адды важнее босса. В героическом режиме закрываем каждую Каталитическую желчь. Инфекции всегда разводим по типу.',heal:'Пики урона: Поглощение, Злокачественный катализатор и смерть Горящего яда. Цель с Сифонной инфекцией не держим в группе — ей нужен отдельный фокус-хил и при необходимости внешний сейв. Для Холи-приста крупные КД лучше разнести по поздним Поглощениям и Катализаторам, а не перекрыть в первом цикле.',phases:[['Маршрут источников','Референс тестового убийства: цикл ~84 сек',[['Поглощение','Imbibe','На 100 энергии босс берёт силу двух ближайших источников. В референс-килле маршрут: Тень+Пламя → Кровь+Пламя → Кровь+Тень, затем повтор.','tank,all','danger','Каждое Поглощение также усиливает постоянный урон от Токсичных испарений.'],['Живые яды','Living Venoms','Два активных источника создают аддов, которые идут к Злокачественной полости. Убить до центра — иначе последует опасный взрыв по рейду.','dps,all','danger'],['Токсичные испарения','Toxic Vapor','После каждого Поглощения постоянный урон по рейду растёт. Поздние циклы опаснее ранних.','healer,all','warning']]],['Постоянные механики','',[['Чумная пена','Plague Froth','Выбранные цели расходятся по назначенным краям. После окончания дебаффа из каждой цели выходят 4 Чумные волны по сторонам света — не направлять через рейд.','all','danger'],['Капающие клыки','Dripping Fangs','Танковский дебафф увеличивает физический урон. Меняться по заранее принятому числу стаков или окну, не ждать аварии.','tank,healer','danger']]],['Героический режим','',[['Злокачественный катализатор','Malignant Catalyst','Сильный рейдовый удар, после которого вокруг центральной полости появляются области Каталитической желчи.','all,healer','danger','Каждую появившуюся область должен перехватить минимум один игрок; заранее распределяем сектора вокруг центра.'],['Горящий яд','Burning Venom','Пульсирует огнём по рейду. После смерти в героическом режиме оставляет на рейде накапливающийся эффект периодического урона.','dps,healer','danger','Не убивать несколько Горящих ядов одновременно без готового рейдового хила.']]],['Адаптивная инфекция','Тип зависит от текущих усилений',[['Сифонная инфекция','Siphoning Infection','Кровь: цель получает мощное поглощение исцеления и снижение получаемого лечения; вынести из группы и фокусно поддерживать.','healer,all','danger'],['Взрывная инфекция','Exploding Infection','Пламя: перед окончанием эффекта уйти как можно дальше от рейда — урон взрыва уменьшается с расстоянием.','all','danger'],['Стигийская инфекция','Stygian Infection','Тень: держать дистанцию от союзников и не попадать в локальные теневые взрывы.','all','warning']]]],timeline:[['0:10','Чумная пена','move'],['0:20','Поглощение — Тень+Пламя','adds'],['0:30','Злокачественный катализатор','raid'],['0:47','Адаптивная инфекция','heal'],['1:44','Поглощение — Кровь+Пламя','adds'],['3:08','Поглощение — Кровь+Тень','adds'],['4:32','Цикл повторяется','move'],['7:20','Последнее Поглощение референса','heal']],spells:[['Поглощение','Imbibe'],['Чумная пена','Plague Froth'],['Злокачественный катализатор','Malignant Catalyst'],['Каталитическая желчь','Catalytic Bile'],['Живые яды','Living Venoms'],['Сифонная инфекция','Siphoning Infection'],['Взрывная инфекция','Exploding Infection'],['Стигийская инфекция','Stygian Infection'],['Токсичные испарения','Toxic Vapor']]},
{ id:'sszorak',order:5,name:'Сззорак',en:'Sszorak',summary:'Heroic-референс 6:30.052: повторяющиеся связки хищника, ядовитых выбросов и перекрёстных ветров с тремя окнами «Зарыться». Главное — не захламлять центр кистами и заранее занимать позицию под отбрасывания.',tags:['Ветер','Кисты','Фронталы','Бурст'],bl:'Лучшее окно — «Зарыться»: в референсе оно начинается примерно на 1:51, 4:09 и 6:27. Если героизм нужен один раз — отдаём в первое полноценное окно или в финальный дожим по плану рейда.',rl:'Босса держим так, чтобы фронталы не пересекали основную группу. На Увечье заранее назначаем группу из минимум пяти игроков для разделения удара. Ядовитый выброс выносится к краям; появившиеся Вязкие кисты не должны закрывать центр. На Бушующих перекрёстных ветрах каждый заранее смотрит своё направление отбрасывания. Перед «Зарыться» вся группа занимает устойчивую позицию и отдаёт бурст.',heal:'Самые опасные моменты Heroic — серия Опустошение → Увечье, отбрасывания ветра и взрывы кист. Для Холи-приста не начинаем длинный каст непосредственно перед ветром. Крупные рейдовые КД удобно разнести на поздние ветра и окна после Ядовитого выброса; внешние сейвы — на танка/назначенную soak-группу Увечья.',phases:[['Основной цикл','Heroic-ритм из референс-боя',[['Высший хищник','Apex Predator','Связка Опустошения и Увечья. Фронтал босса должен смотреть в назначенную сторону; Увечье делится минимум пятью игроками.','tank,all','danger'],['Буря','Tempest','Вихри заставляют быстро менять позицию, но не уводить рейд в будущие точки кист.','all','warning'],['Ядовитый выброс','Venomous Surge','Выбранные игроки выносят механику к краю. После неё появляются Вязкие кисты — центр оставляем чистым.','all','danger'],['Бушующие перекрёстные ветра','Raging Crosswinds','Несколько игроков получают собственные направления отбрасывания. Разойтись так, чтобы не пересечься и не улететь в кисту/край.','all','danger'],['Вязкая киста','Viscous Cyst','Взрыв кисты отбрасывает и оставляет замедляющий яд. Используем только предсказуемые точки по краям.','all','warning']]],['Зарыться','Три окна усиленного урона по боссу',[['Зарыться','Dig In','Сззорак закрепляется во время сильного ветра и получает повышенный входящий урон. Это главное окно для атакующих КД.','dps,all','danger'],['Разъедающий яд','Corroding Venom','Танковский стакающийся эффект усиливает физический урон. Меняемся заранее, особенно перед связкой хищника.','tank,healer','warning']]]],timeline:[['0:09','Опустошение #1','tank'],['0:13','Увечье #1 — soak 5+','raid'],['0:17','Буря #1','move'],['0:32','Ядовитый выброс #1','move'],['0:43','Перекрёстные ветра #1','move'],['1:05','Буря #2','move'],['1:24','Ядовитый выброс #2','move'],['1:36','Перекрёстные ветра #2','move'],['1:51','Зарыться #1 — бурст','burst'],['2:31','Буря #3','move'],['2:50','Ядовитый выброс #3','move'],['3:01','Перекрёстные ветра #3','move'],['3:23','Буря #4','move'],['3:43','Ядовитый выброс #4','move'],['3:54','Перекрёстные ветра #4','move'],['4:09','Зарыться #2 — бурст','burst'],['4:49','Буря #5','move'],['5:08','Ядовитый выброс #5','move'],['5:20','Перекрёстные ветра #5','move'],['5:50','Буря #6','move'],['6:01','Ядовитый выброс #6','move'],['6:12','Перекрёстные ветра #6','move'],['6:27','Зарыться #3 — финал','burst']],spells:[['Высший хищник','Apex Predator'],['Опустошение','Ravage'],['Увечье','Mutilate'],['Буря','Tempest'],['Ядовитый выброс','Venomous Surge'],['Бушующие перекрёстные ветра','Raging Crosswinds'],['Вязкая киста','Viscous Cyst'],['Разъедающий яд','Corroding Venom'],['Зарыться','Dig In']]},
{ id:'fangs',order:6,name:'Двойные Клыки',en:'The Twin Fangs',summary:'Heroic-референс 8:05.636: Вексхул и Итраз живут одновременно, рейд управляет Вечным ядом через шесть Ненасытных трапез и переживает два крупных наложения Потока с Кровавым штормом.',tags:['2 босса','Вечный яд','Трапеза','Soak'],bl:'На старте для ровного клив-урона либо после последней крупной связки, если группа стабильно доходит до 6-й Трапезы. Не расходовать бурст так, чтобы один Клык умер сильно раньше второго.',rl:'Держим здоровье Клыков близким и не допускаем ранней смерти одного босса. Вечный яд отслеживаем на фреймах. Ненасытная трапеза состоит из трёх быстрых ударов: заранее делим рейд на три soak-группы A → B → C, потому что игрок, уже укушенный Трапезой, временно не должен принимать следующий удар. Спиральный ихор выносим на край. Едкие капли перехватываем назначенными игроками. На 100 энергии после Погружения заранее освобождаем сектор под Гнусный поток Вексхула и Кровавый шторм Итраза.',heal:'Главные Heroic-пики — три удара Ненасытной трапезы, Камнелом и наложение Гнусного потока с Кровавым штормом. Для Холи-приста крупные КД лучше разнести между Трапезами #3–#6 и энергофазами около 2:30 и 5:20. Игроки с высоким Вечным ядом и Спиральным ихором требуют отдельного контроля здоровья.',phases:[['Основной цикл','Два босса и постоянный контроль стаков',[['Вечный яд','Eternal Venom','Стаки постоянно накапливаются; в Heroic смертельный порог — 9. Снимаем их через правильно распределённые удары Трапезы.','all','danger'],['Ненасытная трапеза','Ravenous Feast','Три быстрых групповых удара. Группы A → B → C принимают по одному удару, чтобы не ловить усиленный повтор и гарантированно снимать яд.','all','danger'],['Едкий ливень','Caustic Deluge','На активной цели появляются едкие объекты. Назначенные игроки перехватывают их до рейдового взрыва.','all','warning'],['Ядовитое появление','Venomous Emergence','Появляются отродья Вексхула. Быстрый свитч и разворот их фронтала от рейда.','dps,all','danger'],['Спиральный ихор','Coiling Ichor','Несколько игроков выносят уменьшающиеся области на край, оставляя центр свободным.','all','danger'],['Камнелом','Stone Breaker','Назначенная группа принимает удар. Промах по игрокам превращается в тяжёлое наказание всему рейду.','all','danger']]],['100 энергии','Погружение и двойная большая механика',[['Погружение','Submerge','Оба босса меняют позицию; рейд заранее освобождает центральный маршрут.','all','warning'],['Гнусный поток','Vile Flood','Длинный фронтальный поток Вексхула. Уходим в заранее выбранный безопасный сектор.','all','danger'],['Кровавый шторм','Sanguine Storm','Одновременно с Потоком падают кровавые области Итраза. Не запираем себе выход из сектора.','all','danger']]],['Финал','Оба босса должны умереть близко друг к другу',[['Неукрощённая ярость','Uncoiled Wrath','После смерти одного Клыка второй быстро усиливается. Финальный урон распределяем так, чтобы разница HP была минимальной.','dps,all','danger']]]],timeline:[['0:33','Камнелом #1 — soak','raid'],['0:40','Ядовитое появление — отродья','adds'],['1:08','Ненасытная трапеза #1 — A/B/C','raid'],['1:39','Камнелом #2','raid'],['1:56','Спиральный ихор #1 — вынос','move'],['2:16','Ненасытная трапеза #2 — A/B/C','raid'],['2:30','Поток + Кровавый шторм #1','raid'],['3:57','Ненасытная трапеза #3','raid'],['4:27','Камнелом','raid'],['4:46','Спиральный ихор #2','move'],['5:05','Ненасытная трапеза #4','raid'],['5:20','Поток + Кровавый шторм #2','raid'],['5:25','Взбаламутить глубины','move'],['5:49','Едкий ливень','move'],['6:08','Камнелом','raid'],['6:47','Ненасытная трапеза #5','raid'],['7:12','Камнелом','raid'],['7:55','Ненасытная трапеза #6','raid'],['8:06','Убийство — оба босса','burst']],spells:[['Вечный яд','Eternal Venom'],['Ненасытная трапеза','Ravenous Feast'],['Едкий ливень','Caustic Deluge'],['Едкая капля','Caustic Globule'],['Ядовитое появление','Venomous Emergence'],['Отродье Вексхула','Spawn of Vexhul'],['Спиральный ихор','Coiling Ichor'],['Камнелом','Stone Breaker'],['Погружение','Submerge'],['Гнусный поток','Vile Flood'],['Кровавый шторм','Sanguine Storm'],['Взбаламутить глубины','Stir the Depths']]},
{ id:'altar',order:7,name:'Спиральный алтарь',en:'The Coiled Altar',summary:'Многофазный бой. Танковые удары используются для уничтожения объектов и аддов.',tags:['3 фазы','Танк-механика','Рейдовый урон'],bl:'Фаза 3.',rl:'Танк-механика — инструмент, а не просто сейв. Сгустки чистим постепенно. На P3 — заранее расписанные рейд-КД.',heal:'Не перекрывать хил-КД на одиночные взрывы сгустков. Самые крупные КД оставить на финальную фазу.',phases:[['Фаза 1 — Зул’джан','',[['Сгустки яда','Coalesced Venom','Не уничтожать все одновременно — смерть каждого даёт рейдовый урон.','all','danger'],['Рассечение','Sever','Танк направляет удар через нужные сгустки.','tank','danger']]],['Фаза 2 — Малакрасс','',[['Рассечение души','Soul Sever','Танковский удар используется для уничтожения проявлений ужаса.','tank','danger'],['Вечный сумрак','Eternal Nightfall','Быстро пробить защитный эффект — абсолютный приоритет ДД.','dps','danger']]],['Фаза 3 — оба','',[['Финальное наложение механик','Final Overlap','Используем заранее расписанные рейдовые КД и бережём безопасное пространство.','all','danger']]]],timeline:[['P1','Сгустки по одному','raid'],['P2','Ужасы','adds'],['P3','Финальные КД','raid']],spells:[['Сгустки яда','Coalesced Venom'],['Рассечение','Sever'],['Рассечение души','Soul Sever'],['Вечный сумрак','Eternal Nightfall']]},
{ id:'ulatek',order:8,name:'Ула’тек',en:"Ula'tek",summary:'Финальный босс: яйца, волны яда, адды и постепенно исчезающее безопасное пространство.',tags:['Финал','Яйца','Пространство','Интермиссия'],bl:'Фаза 3, чтобы сократить разрушение арены.',rl:'Яд не должен касаться лишних яиц. Общие кольца — весь рейд внутрь. На P3 экономить КД уже нельзя.',heal:'Следить за накопившимися DoT от ошибочно активированных яиц. Рейдовые КД — на Кольца и позднюю P3.',phases:[['Фазы 1–2','',[['Едкие волны','Caustic Waves','Уворачиваемся и не позволяем волнам задевать лишние яйца.','all','danger'],['Материнский гнев',"Mother's Wrath",'После отбрасывания танк немедленно возвращается в ближний бой.','tank','danger'],['Спектральные кольца','Spectral Coils','Большой общий soak — практически весь рейд внутрь.','all','danger'],['Ядовитое сердце','Venomous Heart','Короткое окно повышенного урона — заранее готовим бурст.','dps','warning']]],['Интермиссия','',[['Стражи Роковой чешуи','Doomscale Wardens','Высокий приоритет: не дать активировать лишние яйца.','dps','danger']]],['Фаза 3','',[['Разрушение','Demolish','Безопасная арена уменьшается — героизм и дожим босса.','all','danger']]]],timeline:[['P1','Волны и яйца','move'],['Интермиссия','Стражи','adds'],['P3','BL + дожим','burst']],spells:[['Едкие волны','Caustic Waves'],['Материнский гнев',"Mother's Wrath"],['Спектральные кольца','Spectral Coils'],['Ядовитое сердце','Venomous Heart'],['Разрушение','Demolish']]}
];
