          const ids=new Set((fresh[i].tokens||[]).map(t=>t[0]));
          const hasRoster=keep.some(t=>['roster','class'].includes(t?.[5]?.kind));
          if(hasRoster)fresh[i].tokens=(fresh[i].tokens||[]).filter(t=>!['tank','healer','melee','ranged'].includes(t?.[2]));
