function raidPlanTextRichHtml(t){
  const m=raidPlanNativeMeta(t),raw=String(m?.text??t?.[1]??'');
  if(!Array.isArray(m?.styles)||!m.styles.length)return esc(raw).replace(/\n/g,'<br>');
  const marks=[];
  for(const r of m.styles){const a=Math.max(0,Math.min(raw.length,Number(r?.start)||0)),b=Math.max(a,Math.min(raw.length,Number(r?.end)||a));if(b>a)marks.push({a,b,style:r.style||{}})}
  if(!marks.length)return esc(raw).replace(/\n/g,'<br>');
  const cuts=new Set([0,raw.length]);for(const r of marks){cuts.add(r.a);cuts.add(r.b)}const pts=[...cuts].sort((a,b)=>a-b);let out='';
  for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],seg=raw.slice(a,b);if(!seg)continue;const active=marks.filter(r=>a>=r.a&&b<=r.b).map(r=>r.style);let css='';if(active.some(x=>x.fontWeight==='bold'||Number(x.fontWeight)>=600))css+='font-weight:700;';if(active.some(x=>x.underline||x.textDecoration==='underline'))css+='text-decoration:underline;';if(active.some(x=>x.fontStyle==='italic'))css+='font-style:italic;';const color=active.map(x=>x.fill||x.color).find(Boolean);if(color)css+=`color:${esc(color)};`;out+=css?`<span style="${css}">${esc(seg).replace(/\n/g,'<br>')}</span>`:esc(seg).replace(/\n/g,'<br>')}
  return out;
}
function raidPlanNumber(v){return v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))?Number(v):null}
function raidPlanTokenStyle(t){
  const m=raidPlanNativeMeta(t);if(!m)return '';
  const st=[],w=raidPlanNumber(m.w),h=raidPlanNumber(m.h),font=raidPlanNumber(m.fontCqw),angle=raidPlanNumber(m.angle),opacity=raidPlanNumber(m.opacity),z=raidPlanNumber(m.z);
  if(w!==null)st.push(`--rp-w:${w}%`);if(h!==null)st.push(`--rp-h:${h}%`);if(font!==null)st.push(`--rp-font:${font}`);if(m.fill)st.push(`--rp-color:${m.fill}`);if(m.backgroundColor)st.push(`--rp-bg:${m.backgroundColor}`);if(m.textAlign)st.push(`--rp-text-align:${m.textAlign}`);if(m.verticalAlign)st.push(`--rp-vertical-align:${m.verticalAlign}`);if(raidPlanNumber(m.lineHeight)!==null)st.push(`--rp-line-height:${Math.max(.6,Math.min(3,raidPlanNumber(m.lineHeight)))}`);if(m.fontFamily)st.push(`--rp-font-family:${m.fontFamily}`);if(m.fontWeight!==null&&m.fontWeight!==undefined)st.push(`--rp-font-weight:${m.fontWeight}`);if(angle!==null)st.push(`--rp-angle:${angle}deg`);if(m.ringColor)st.push(`--rp-ring:${m.ringColor}`);if(opacity!==null)st.push(`--rp-opacity:${Math.max(0,Math.min(1,opacity))}`);if(z!==null)st.push(`z-index:${Math.max(1,Math.min(80,10+Math.round(z)))}`);return st.join(';');
}
