function togglePaths(){showPaths=!showPaths;save();render()}
function raidPlanColorWithAlpha(color,alpha){
  const c=String(color||'transparent').trim();
  const a=raidPlanNumber(alpha);if(a===null)return c;const x=Math.max(0,Math.min(1,a));
  let m=c.match(/^#([0-9a-f]{3})$/i);if(m){const h=m[1];return `rgba(${parseInt(h[0]+h[0],16)},${parseInt(h[1]+h[1],16)},${parseInt(h[2]+h[2],16)},${x})`}
  m=c.match(/^#([0-9a-f]{6})$/i);if(m){const h=m[1];return `rgba(${parseInt(h.slice(0,2),16)},${parseInt(h.slice(2,4),16)},${parseInt(h.slice(4,6),16)},${x})`}
  m=c.match(/^rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)(?:\s*,\s*([0-9.]+))?\s*\)$/i);
  if(m){const embedded=m[4]==null?1:Math.max(0,Math.min(1,+m[4]||0));return `rgba(${m[1]},${m[2]},${m[3]},${embedded*x})`}
  return `color-mix(in srgb, ${c} ${x*100}%, transparent)`;
}
function effectHtml(e,editable=false){
  const rp=e?.raidPlan?.native,shape=e?.raidPlan?.shapeKind||'',svgPath=rp&&e?.raidPlan?.svgPath?.d?e.raidPlan.svgPath:null;
  // RaidPlan `line` + endType=drawn is the planner's native arrow object.
  // Render line/arrow vectors as SVG instead of the generic CSS pill/clip-path:
  // the latter loses RaidPlan arrow geometry and can turn imported vectors into
  // white blobs when source dimensions are large.
  const nativeVectorLine=!!(rp&&!svgPath&&(e?.type==='line'||e?.type==='arrow'));
  const vectorBoxH=e?.type==='arrow'?3.6:Math.max(1.5,Math.min(3,+e.h||1.5));
  const styleParts=[`left:${e.x}%`,`top:${e.y}%`,`width:${e.w}%`,`height:${nativeVectorLine?vectorBoxH:e.h}%`,`--rot:${Number(e.rot)||0}deg`];
  if(rp){
    const fillAlpha=raidPlanNumber(e.raidPlan.fillOpacity),strokeAlpha=raidPlanNumber(e.raidPlan.strokeOpacity);
    styleParts.push(`--rp-h:${Math.max(.08,+e.h||.5)}%`,`--rp-stroke:${raidPlanColorWithAlpha(e.raidPlan.stroke||'transparent',strokeAlpha)}`,`--rp-fill:${raidPlanColorWithAlpha(e.raidPlan.fill||'transparent',fillAlpha)}`);
    const strokeWidth=raidPlanNumber(e.raidPlan.strokeWidth),opacity=raidPlanNumber(e.raidPlan.opacity),shapeFont=raidPlanNumber(e.raidPlan.shapeFontCqw),z=raidPlanNumber(e.raidPlan.z);
    if(strokeWidth!==null)styleParts.push(`--rp-stroke-w:${Math.max(.05,strokeWidth)}px`);
    if(opacity!==null)styleParts.push(`--rp-opacity:${Math.max(0,Math.min(1,opacity))}`);
    if(shapeFont!==null)styleParts.push(`--rp-shape-font:${shapeFont}`);
    if(e.raidPlan.labelFill)styleParts.push(`--rp-label-color:${e.raidPlan.labelFill}`);
    if(z!==null)styleParts.push(`z-index:${Math.max(1,Math.min(90,10+Math.round(z)))}`);
  }
  if(svgPath||nativeVectorLine)styleParts.push('background:transparent','border:0','border-radius:0','box-shadow:none','overflow:visible');
  const shapeCls=e.type==='zone'?(shape==='rect'?' raidplanNativeRect':shape==='ellipse'?' raidplanNativeEllipse':shape==='circle'?' raidplanNativeCircle':shape==='polygon'?' raidplanNativePolygon':' raidplanNativeZone'):'';
  const cls=svgPath
    ?`effect raidplanNativeEffect raidplanNativeSvgPath ${editable?'editable':''}`
    :(nativeVectorLine
      ?`effect raidplanNativeEffect raidplanNativeSvgLine ${editable?'editable':''}`
      :`effect ${e.type} ${rp?'raidplanNativeEffect '+(e.type==='arrow'?'raidplanNativeArrow':e.type==='line'?'raidplanNativeLine':e.type==='zone'?'raidplanNativeZone':'')+shapeCls:''} ${editable?'editable':''}`);
  let inner='';
  if(svgPath){
    const vb=Array.isArray(svgPath.viewBox)&&svgPath.viewBox.length===4?svgPath.viewBox:[0,0,100,100];
    const fill=svgPath.fill&&svgPath.fill!=='transparent'?svgPath.fill:'none',stroke=svgPath.stroke||'#ffffff',sw=Math.max(.05,Number(svgPath.strokeWidth)||3);
    inner=`<svg aria-hidden="true" viewBox="${vb.map(Number).join(' ')}" preserveAspectRatio="none" style="display:block;width:100%;height:100%;overflow:visible;pointer-events:none"><path d="${esc(svgPath.d)}" fill="${esc(fill)}" stroke="${esc(stroke)}" stroke-width="${sw}" stroke-linecap="${esc(svgPath.lineCap||'round')}" stroke-linejoin="${esc(svgPath.lineJoin||'round')}"/></svg>`;
  }else if(nativeVectorLine){
    const sourceSw=Math.max(2,Number(e?.raidPlan?.strokeWidth)||3);
    const startArrow=/drawn|arrow/i.test(String(e?.raidPlan?.startType||''));
    const endArrow=e?.type==='arrow'||/drawn|arrow/i.test(String(e?.raidPlan?.endType||''));
    const x1=startArrow?14:2,x2=endArrow?86:98;
    const startHead=startArrow?`<path d="M 18 3 L 2 10 L 18 17"/>`:'';
    const endHead=endArrow?`<path d="M 82 3 L 98 10 L 82 17"/>`:'';
    inner=`<svg aria-hidden="true" viewBox="0 0 100 20" preserveAspectRatio="none" style="display:block;width:100%;height:100%;overflow:visible;pointer-events:none;fill:none;stroke:var(--rp-stroke,#fff);stroke-width:${sourceSw}px;stroke-linecap:round;stroke-linejoin:round"><path d="M ${x1} 10 L ${x2} 10"/>${startHead}${endHead}</svg>`;
  }else if(rp&&e?.raidPlan?.shapeLabel)inner=`<span class="rpNativeShapeLabel">${esc(e.raidPlan.shapeLabel).replace(/\n/g,'<br>')}</span>`;
  return `<div class="${cls}" data-effect="${e.id}" style="${styleParts.join(';')}" title="${esc(e.label||'')}">${inner}</div>`;
}

function boxOverlap(a,b,pad=0){
  return !(a.r+pad<b.l || a.l-pad>b.r || a.b+pad<b.t || a.t-pad>b.b);
}
function effectLabelLayout(sc,{ignoreManual=false}={}){
  const tokens=(sc.tokens||[]).map(t=>({
    l:+t[3]-3.1,r:+t[3]+3.1,t:+t[4]-4.2,b:+t[4]+4.2
  }));
  const placed=[];
  return (sc.effects||[]).map((e,i)=>{
    if(e?.raidPlan?.hideLabel)return null;
    const label=String(e.label||effectLabels[e.type]||'').trim();
    if(!label)return null;

    const lw=Math.max(9,Math.min(30,label.length*.58+4.5));
    const lh=5.2;
    const ew=Math.max(4,+e.w||12),eh=Math.max(4,+e.h||12);
    const ex=Number.isFinite(+e.x)?+e.x:50,ey=Number.isFinite(+e.y)?+e.y:50;
    const manual=!ignoreManual&&Number.isFinite(+e.labelDx)&&Number.isFinite(+e.labelDy);

    // Ручная позиция хранится как смещение от эффекта: если сам эффект двигают,
    // подпись следует за ним и сохраняет выбранное пользователем расположение.
    if(manual){
      const x=Math.max(lw/2+1.2,Math.min(100-lw/2-1.2,ex+(+e.labelDx||0)));
      const y=Math.max(lh/2+1.2,Math.min(100-lh/2-1.2,ey+(+e.labelDy||0)));
      const box={l:x-lw/2,r:x+lw/2,t:y-lh/2,b:y+lh/2};
      placed.push(box);
      return {x,y,box,pos:'manual',score:0,label,type:e.type,id:e.id,manual:true,anchorX:ex,anchorY:ey};
    }

    const dx=ew/2+lw/2+2.7,dy=eh/2+lh/2+2.8;
    const candidates=[
      {x:ex,y:ey-eh/2-3.6,pos:'top',base:0},
      {x:ex,y:ey+eh/2+3.6,pos:'bottom',base:1.5},
      {x:ex-ew/2-lw/2-2.5,y:ey,pos:'left',base:4},
      {x:ex+ew/2+lw/2+2.5,y:ey,pos:'right',base:4},
      {x:ex-dx*.72,y:ey-dy*.72,pos:'top-left',base:2.7},
      {x:ex+dx*.72,y:ey-dy*.72,pos:'top-right',base:2.7},
      {x:ex-dx*.72,y:ey+dy*.72,pos:'bottom-left',base:3.2},
      {x:ex+dx*.72,y:ey+dy*.72,pos:'bottom-right',base:3.2},
      {x:ex,y:ey-3,pos:'inside',base:28}
    ];

    let best=null;
    for(const c of candidates){
      const rawX=c.x,rawY=c.y;
      const x=Math.max(lw/2+1.2,Math.min(100-lw/2-1.2,rawX));
      const y=Math.max(lh/2+1.2,Math.min(100-lh/2-1.2,rawY));
      const box={l:x-lw/2,r:x+lw/2,t:y-lh/2,b:y+lh/2};
      let score=c.base+Math.abs(x-rawX)*9+Math.abs(y-rawY)*9;

      for(const tb of tokens){
        if(boxOverlap(box,tb,1.35))score+=210;
      }
      for(const pb of placed){
        if(boxOverlap(box,pb,1.75))score+=290;
      }

      const effectBox={l:ex-ew/2,r:ex+ew/2,t:ey-eh/2,b:ey+eh/2};
      if(c.pos!=='inside' && boxOverlap(box,effectBox,.65))score+=90;

      if(!best||score<best.score)best={x,y,box,pos:c.pos,score,label,type:e.type,id:e.id,manual:false,anchorX:ex,anchorY:ey};
    }
    placed.push(best.box);
    return best;
  }).filter(Boolean);
}
function effectLabelsHtml(sc,{editable=false}={}){
  const layout=effectLabelLayout(sc);
  const leaders=layout.filter(x=>x.manual&&Math.hypot(x.x-x.anchorX,x.y-x.anchorY)>3.5).map(x=>`<line class="effectLabelLeader" data-effect-label-line="${x.id}" x1="${x.anchorX}" y1="${x.anchorY}" x2="${x.x}" y2="${x.y}" vector-effect="non-scaling-stroke"></line>`).join('');
  return `<div class="effectLabels ${editable?'editable':''}"><svg class="effectLabelLeaders" viewBox="0 0 100 100" preserveAspectRatio="none">${leaders}</svg>${layout.map(x=>`<div class="effectCallout ${x.type} ${editable?'editable':''} ${x.manual?'manual':''}" data-effect-label="${x.id}" style="left:${x.x}%;top:${x.y}%" title="${editable?'Перетащи подпись. Shift — только по одной оси. Двойной клик или ПКМ — вернуть авто-позицию.':''}"><span>${esc(x.label)}</span></div>`).join('')}</div>`;
}
