  layout.forEach(p=>{const fx=sc.effects.find(x=>x.id===p.id);if(!fx)return;fx.labelDx=+(p.x-(+fx.x||50)).toFixed(3);fx.labelDy=+(p.y-(+fx.y||50)).toFixed(3)});
