function setPlayerSpeed(v){playerSpeed=+v||1}
function animatePlayerTo(target){
  const bs=scenarioState(current),arena=el('#playerArena');target=Math.max(0,Math.min(bs.scenes.length-1,+target||0));if(!arena){playerSceneIndex=target;render();return}
  const sourceIndex=playerSceneIndex,source=bs.scenes[sourceIndex]||bs.scenes[0],sc=bs.scenes[target];
  const oldNodes=[...arena.querySelectorAll('.token')],newMap=new Map(sc.tokens.map(t=>[t[0],t]));
  let longest=0;
  oldNodes.forEach(n=>{
    const t=newMap.get(n.dataset.id);
    if(!t){n.classList.add('vanish');return}
    const route=(source.routes?.[n.dataset.id]||[]).map(p=>({x:p.x,y:p.y}));
    const path=[...route,{x:t[3],y:t[4]}];
    const total=Math.max(.5,Math.min(5,(source.duration||8)/playerSpeed)),seg=Math.max(.2,total/Math.max(1,path.length));
    n.innerHTML=tokenInnerHtml(t);n.className='token '+t[2]+tokenExtraClass(t)+' moving';n.style.setProperty('--moveDur',seg+'s');
    path.forEach((p,i)=>setTimeout(()=>{n.style.left=p.x+'%';n.style.top=p.y+'%'},i*seg*1000+20));
    longest=Math.max(longest,total);newMap.delete(n.dataset.id);
  });
  newMap.forEach(t=>{const n=document.createElement('div');n.className='token '+t[2]+' appear';n.style.setProperty('--moveDur','.45s');n.dataset.id=t[0];n.style.left=t[3]+'%';n.style.top=t[4]+'%';n.innerHTML=tokenInnerHtml(t);n.className='token '+t[2]+tokenExtraClass(t)+' appear';arena.querySelector('.tokens').appendChild(n);requestAnimationFrame(()=>n.classList.remove('appear'))});
  const effects=arena.querySelector('.effects');effects.innerHTML=sc.effects.map(e=>effectHtml(e,false)).join('');effects.querySelectorAll('.effect').forEach(n=>n.classList.add('fxIn'));
  const labels=arena.querySelector('.effectLabels');if(labels)labels.outerHTML=effectLabelsHtml(sc);
  const lab=arena.querySelector('.arenaLabel');if(lab)lab.textContent=sc.name;
  playerSceneIndex=target;setTimeout(()=>{if(view==='player')render()},(longest*1000)+250);
}
function togglePlayback(){
  if(playerPlaying){stopPlayback();render();return}
  const bs=scenarioState(current),events=[...bs.timelineV3].sort((a,b)=>a.time-b.time);if(!events.length){toast('Таймлайн пуст');return}
  playerPlaying=true;playerSceneIndex=events[0].scene;render();
  const base=events[0].time; events.forEach((e,i)=>{const delay=((e.time-base)*1000)/playerSpeed;const id=setTimeout(()=>{if(!playerPlaying)return;animatePlayerTo(e.scene);toast(`${fmtTime(e.time)} · ${e.label}`);if(i===events.length-1){playbackTimer=setTimeout(()=>{playerPlaying=false;if(view==='player')render()},Math.max(1200,(scenarioState(current).scenes[e.scene]?.duration||5)*600/playerSpeed))}},delay);(state._playTimers||(state._playTimers=[])).push(id)})
}
function stopPlayback(){playerPlaying=false;(state._playTimers||[]).forEach(clearTimeout);state._playTimers=[];if(playbackTimer)clearTimeout(playbackTimer);playbackTimer=null}
